def told(agent, value, belief_state):
    """The result of agent being told the value."""
    if agent == 'Albert':
        return satisfy(lambda d: month(d) == value, belief_state)
    elif agent == 'Bernard':
        return satisfy(lambda d: day(d) == value, belief_state)
    else:
        raise ValueError(f'unknown agent: {agent}')
